window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-453a93683b8ccee7"]={"versions": [{"id": "FIG-453a93683b8ccee7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>act Increment Counter</code>) im Kontext der AUTOSAR End-to-End-Bibliothek (E2E Library). Es spezifiziert den internen Ablauf zur Aktualisierung des E2E-Sequenzzählers (<code>Counter</code>) innerhalb der Zustandsdatenstruktur (<code>State</code>) bei der Absicherung bzw. Prüfung von Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>State</code>: Datenstruktur für den Zustand der E2E-Kommunikation.</li>\n<li><code>State-&gt;Counter</code>: Numerischer Zählerwert (Modulo-16-Zähler, Wertebereich 0 bis 15) innerhalb des Übertragungszustands.</li>\n<li>Kontrollknoten: Startknoten (Initial Node), zwei Entscheidungsknoten (Decision Node / Merge Node) und ein Endknoten (Activity Final Node).</li>\n<li>Aktionen: <code>State-&gt;Counter ++</code> (Inkrementierung) und <code>State-&gt; Counter = 0</code> (Rücksetzen des Zählers).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Aktivität am Initialknoten (<code>Increment State-&gt;Counter</code>).</li>\n<li>Prüfung der Verzweigungsbedingung am Entscheidungsknoten: <code>State-&gt;Counter &lt; 15 ?</code>.</li>\n<li>Zweig <code>[TRUE]</code>: Ist der Zähler kleiner als 15, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Zweig <code>[FALSE]</code>: Hat der Zähler den Grenzwert 15 erreicht oder überschritten, wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Zusammenführung der Kontrollflüsse im Merge-Knoten und Weiterleitung an den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensspezifikation für E2E-Profile mit 4-Bit-Zähler (z. B. E2E-Profil 1). Der Zähler muss zyklisch im Intervall 0 bis 15 inkrementiert werden und nach 15 wieder auf 0 überlaufen (Modulo-16-Arithmetik). Die Implementierung in Software muss diesen Überlauf zwingend abbilden, um Protokollsynchronität zwischen Sender und Empfänger zu gewährleisten.</p>"}, {"id": "FIG-4f42b4f75e411f9d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext der AUTOSAR End-to-End-Bibliothek (E2E Library). Es stellt den Ablauf zur Aktualisierung des Zählers (<code>Counter</code>) in der Zustandsstruktur <code>State</code> dar, ohne formalen Aktivitätsrahmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>State</code>: Datenstruktur für den Zustand der E2E-Kommunikation.</li>\n<li><code>State-&gt;Counter</code>: Numerischer Zählerwert (Modulo-16-Zähler, Wertebereich 0 bis 15) innerhalb des Übertragungszustands.</li>\n<li>Kontrollknoten: Startknoten (Initial Node), zwei Entscheidungsknoten (Decision Node / Merge Node) und ein Endknoten (Activity Final Node).</li>\n<li>Aktionen: <code>State-&gt;Counter ++</code> (Inkrementierung) und <code>State-&gt; Counter = 0</code> (Rücksetzen des Zählers).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start der Aktivität am Initialknoten (<code>Increment State-&gt;Counter</code>).</li>\n<li>Prüfung der Verzweigungsbedingung am Entscheidungsknoten: <code>State-&gt;Counter &lt; 15 ?</code>.</li>\n<li>Zweig <code>[TRUE]</code>: Ist der Zähler kleiner als 15, wird die Aktion <code>State-&gt;Counter ++</code> ausgeführt.</li>\n<li>Zweig <code>[FALSE]</code>: Hat der Zähler den Grenzwert 15 erreicht oder überschritten, wird die Aktion <code>State-&gt; Counter = 0</code> ausgeführt.</li>\n<li>Zusammenführung der Kontrollflüsse im Merge-Knoten und Weiterleitung an den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verhaltensspezifikation für E2E-Profile mit 4-Bit-Zähler (z. B. E2E-Profil 1). Der Zähler muss zyklisch im Intervall 0 bis 15 inkrementiert werden und nach 15 wieder auf 0 überlaufen (Modulo-16-Arithmetik). Die Implementierung in Software muss diesen Überlauf zwingend abbilden, um Protokollsynchronität zwischen Sender und Empfänger zu gewährleisten.</p>"}], "trans": [{"from": "FIG-453a93683b8ccee7", "to": "FIG-4f42b4f75e411f9d", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Rahmenelement: Der umgebende UML-Aktivitätsrahmen mit der Kopfzeile <code>act Increment Counter</code> sowie die äußere Begrenzungslinie fehlen.</li>\n<li>Startknoten-Beschriftung: Das Wort <code>Increment</code> oberhalb von <code>State-&gt;Counter</code> am Initialknoten ist abgeschnitten bzw. entfallen.</li>\n<li>Verzweigungsbedingung: Die Bedingung an der oberen Entscheidungselement-Raute ist am rechten Bildrand abgeschnitten (<code>State-&gt;Co</code> / <code>?</code> statt <code>State-&gt;Counter &lt; 15 ?</code>).</li>\n<li>Bildzuschnitt: Der gesamte Bildausschnitt ist enger und an den Rändern beschnitten.</li>\n</ul>"}]};
